'use strict';
let researchReport=null,researchBusy=false,alertController=null,alertTimer=null;
const alertReports=new Map();
/** 为新市场初始化研究日期和货币，同时清空跨市场提醒。 */
function resetResearchMarket() {researchReport=null;alertReports.clear();alertController?.abort();clearInterval(alertTimer);alertTimer=null;$('auto-alerts').checked=false;$('research-symbol').value=marketConfig().example;$('research-date').min=marketDate(-365);$('research-date').max=marketDate(-1);$('research-date').value=state.date||state.meta?.tradingDates?.at(-1)||marketDate(-1);$('research-money-unit').textContent=marketConfig().money;$('alert-list').innerHTML='';$('alert-count').textContent='待扫描';$('alert-status').textContent='尚未扫描此市场；近5个已结束交易日，不包含盘中未完成资金。';$('research-content').innerHTML='<div class="research-empty">选择股票和研究口径，查看真实资金事件。</div>';}
/** 根据日级或分钟口径说明阈值与缺失历史，禁用不适用的参数。 */
function updateResearchKind() {const tail=$('research-kind').value!=='daily';$('research-span').disabled=tail;$('research-percentile').disabled=tail;$('research-explanation').textContent=tail?'尾盘净额=收盘累计主力净额−10/20分钟前累计净额。仅使用本机已留存且完整覆盖的分钟窗口；金额下限用于过滤较小信号。历史分钟无法按日期补取。':'异常阈值取事件发生前60个同跨度窗口的同向净额绝对值分位数，至少10个有效样本；同时满足金额下限。连续区间大于1时，按区间末日收盘观察随后走势。';}
/** 打开资金事件窗口，沿用当前市场与历史日期，不自动使用其他日期数据。 */
function openResearch(symbol=marketConfig().example,kind='daily') {if(researchBusy){$('research-dialog').showModal();return;}$('research-symbol').value=symbol;$('research-kind').value=kind;$('research-date').min=marketDate(-365);$('research-date').max=marketDate(-1);$('research-date').value=state.date||state.meta?.tradingDates?.at(-1)||marketDate(-1);$('research-money-unit').textContent=marketConfig().money;updateResearchKind();$('research-dialog').showModal();if(state.endpoint)queryResearch();else $('research-content').innerHTML='<div class="research-empty">请先在看板连接行情服务。新版服务支持尾盘留存、历史事件和大额净流出提醒。</div>';}
/** 为单股研究生成明确的市场、区间、阈值和持有期参数。 */
function researchEndpoint(symbol,kind='daily') {if(!state.endpoint)throw new Error('请先连接行情服务。');const endpoint=new URL(state.endpoint);endpoint.pathname=endpoint.pathname.replace(/\/snapshot$/, '/research');endpoint.search='';const parameters={market:state.market,symbol,kind,direction:$('research-direction').value,date:$('research-date').value,lookback:$('research-lookback').value,span:$('research-span').value,percentile:$('research-percentile').value,minimum:$('research-minimum').value,days:$('research-days').value};for(const [key,value] of Object.entries(parameters))endpoint.searchParams.set(key,value);return endpoint;}
/** 校验研究数据来源及市场，拒绝将其他标的结果带入当前窗口。 */
function validateResearch(report,symbol) {if(report.source!=='futu-opend'||report.market!==state.market||report.unit!==marketConfig().unit||report.symbol!==symbol||report.adjustment!=='QFQ'||!Array.isArray(report.events)||!Array.isArray(report.summary))throw new Error('资金研究返回格式或市场不匹配。');return report;}
/** 查询真实历史事件并保留错误后的重试入口。 */
async function queryResearch(event) {event?.preventDefault();if(researchBusy||!$('research-form').reportValidity())return;researchBusy=true;window.flowResearchBusy=true;document.querySelectorAll('#research-form input,#research-form select').forEach(el=>{el.disabled=true;});$('research-query').disabled=true;$('research-query').textContent='正在研究…';$('market-select').disabled=true;$('research-content').innerHTML='<div class="research-empty">正在读取真实日级资金、分钟留存与前复权价格…</div>';try{const symbol=marketSymbol($('research-symbol').value),endpoint=researchEndpoint(symbol,$('research-kind').value),report=await requestJson(endpoint,progress=>{$('research-content').textContent=(progress.message||'等待查询')+' · '+(progress.done||0)+' / '+(progress.total||1);});researchReport=validateResearch(report,symbol);renderResearch();}catch(error){researchReport=null;$('research-content').innerHTML='<div class="research-empty validation-error">'+escapeHtml(error.message)+'</div><button class="button" data-retry-research>重试此次研究</button>';}finally{researchBusy=false;window.flowResearchBusy=false;document.querySelectorAll('#research-form input,#research-form select').forEach(el=>{el.disabled=false;});updateResearchKind();$('research-query').disabled=false;$('research-query').textContent='查询真实事件';updateHistoryControls();}}
/** 用有效数据标记方向，未取得数据时显示缺失而不是中性信号。 */
function flowDirection(value) {return !Number.isFinite(value)?'无完整数据':value>0?'净流入':value<0?'净流出':'净额为零';}
/** 展示尾盘覆盖、事件列表和逐日统计；未满X天的样本按实际可观察日计数。 */
function renderResearch() {const r=researchReport;if(!r)return;const recent=r.recentAlerts||[],tail=r.tailLatest||{windows:[]},kind=r.kind==='daily'?'日级资金异常':r.kind==='tail10'?'尾盘10分钟':'尾盘20分钟';$('research-content').innerHTML='<div class="research-result-heading"><h3>'+escapeHtml(r.symbol)+' / '+escapeHtml(r.name)+'</h3><span>'+escapeHtml(r.start)+' — '+escapeHtml(r.asOf)+' · '+kind+'</span></div><div class="research-metrics">'+tail.windows.map(item=>'<div><span>尾盘 '+item.minutes+' 分钟 · '+escapeHtml(tail.date||'尚未留存')+'</span><strong class="'+tone(item.main)+'">'+number(item.main,0,true)+'</strong><small>'+flowDirection(item.main)+' · '+(item.complete?'完整窗口':escapeHtml(item.reason||'尚无记录'))+'</small></div>').join('')+'<div><span>研究事件 / 有效资金日</span><strong>'+r.events.length+' / '+r.coverage.available+'</strong><small>回看 '+r.coverage.requested+' 个交易日 · '+marketConfig().money+'</small></div></div>'+(r.kind!=='daily'?'<div class="validation-note">完整尾盘覆盖 '+r.coverage.available+' / '+r.coverage.requested+' 日。未留存或缺分钟的日期不会进入分析；不是用日级净额估算尾盘。服务需在采集时保持运行，观察池分钟数据每3分钟留存。</div>':'')+(r.minuteError?'<p class="validation-error">'+escapeHtml(r.minuteError)+'；日级研究仍可查看。</p>':'')+'<p class="method-caption">'+escapeHtml(r.method)+'</p><h3 class="section-heading">近5个交易日提醒 <span class="signal-badge">'+recent.length+'</span></h3>'+(recent.length?'<div class="alert-list">'+recent.map(event=>'<button class="alert-item" data-research-event="'+r.events.findIndex(item=>item.date===event.date&&item.start===event.start)+'"><span><strong>'+escapeHtml(event.start)+' → '+escapeHtml(event.date)+'</strong><small>异常阈值 '+number(event.threshold,0)+' '+marketConfig().money+'</small></span><strong class="negative">'+number(event.main,0,true)+' <small>'+marketConfig().money+'</small></strong><span>查看随后走势 ↗</span></button>').join('')+'</div>':'<p class="research-muted">未发现符合当前阈值的近期大额净流出事件；不代表没有资金流出。</p>')+'<h3 class="section-heading">历史资金事件 <span class="muted">点击某行看随后每天的价格</span></h3>'+(r.events.length?'<div class="path-table"><table><thead><tr><th>区间起点</th><th>事件结束日</th><th>主力净额</th><th>此前样本 / 阈值</th><th>已观察 / X</th><th>最后可观察累计涨跌</th></tr></thead><tbody>'+[...r.events].sort((a,b)=>Math.abs(b.main)-Math.abs(a.main)).map(event=>{const final=event.path.at(-1);return '<tr class="event-row" tabindex="0" role="button" data-research-event="'+r.events.indexOf(event)+'" aria-label="查看 '+event.date+' 之后的走势"><td>'+escapeHtml(event.start)+'</td><td>'+escapeHtml(event.date)+'</td><td class="'+tone(event.main)+'">'+number(event.main,0,true)+'</td><td>'+event.baselineSamples+' / '+number(event.threshold,0)+'</td><td>'+event.availableDays+' / '+r.requestedDays+'</td><td class="'+tone(final?.cumulative)+'">'+number(final?.cumulative,2,true)+(Number.isFinite(final?.cumulative)?'%':'')+'</td></tr>';}).join('')+'</tbody></table></div>':'<div class="research-empty">'+(r.kind!=='daily'&&!r.coverage.available?'尚无完整历史尾盘窗口；留存后可研究真实尾盘方向与后续价格。':'此区间没有符合阈值的资金事件，或此前同向基线样本不足10个。')+'</div>')+'<div id="research-event-detail"></div>'+renderResearchSummary(r);if(r.events.length)showResearchEvent(0);}
/** 展示每个后续交易日的有效样本数、平均实际收益和上涨率。 */
function renderResearchSummary(report) {if(!report.events.length)return '';return '<h3 class="section-heading">事件后 T+1 至 T+'+report.requestedDays+' 的实际表现</h3><p class="research-muted">上涨率是历史描述，不是未来上涨概率；重叠事件并非独立样本，缺失或未满期数据不进入该日分母。</p><div class="path-table summary-table"><table><thead><tr><th>后续交易日</th><th>有效事件数</th><th>平均累计涨跌</th><th>上涨比例</th></tr></thead><tbody>'+report.summary.map(item=>'<tr><td>T+'+item.day+'</td><td>'+item.samples+'</td><td class="'+tone(item.average)+'">'+number(item.average,2,true)+(Number.isFinite(item.average)?'%':'')+'</td><td>'+percent(item.upRate,1)+'</td></tr>').join('')+'</tbody></table></div>';}
/** 展示选中资金事件的每日真实价格，原始价格缺失时保留断点。 */
function showResearchEvent(index) {const r=researchReport,event=r?.events[index];if(!event)return;const rows=event.path;$('research-event-detail').innerHTML='<h3 class="section-heading">'+escapeHtml(event.date)+' · '+flowDirection(event.main)+' '+number(event.main,0,true)+' '+marketConfig().money+'，之后怎样走</h3>'+(rows.length?pathChart(rows)+'<div class="path-table"><table><thead><tr><th>交易日</th><th>日期</th><th>前复权收盘</th><th>单日涨跌</th><th>相对事件日累计</th></tr></thead><tbody>'+rows.map(row=>'<tr><td>T+'+row.day+'</td><td>'+escapeHtml(row.date)+'</td><td>'+number(row.close,2)+'</td><td class="'+tone(row.change)+'">'+number(row.change,2,true)+(Number.isFinite(row.change)?'%':'')+'</td><td class="'+tone(row.cumulative)+'">'+number(row.cumulative,2,true)+(Number.isFinite(row.cumulative)?'%':'')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="validation-error">事件日收盘缺失，无法计算后续收益；资金事件仍保留。</p>')+'<p class="research-muted">区间资金截至 '+escapeHtml(event.date)+'；后续收益以该日收盘为基准，不能解释为下一日实际可成交的策略收益。</p>';document.querySelectorAll('[data-research-event]').forEach(el=>el.classList.toggle('selected-event',Number(el.dataset.researchEvent)===index));}
/** 扫描自选或当前观察池最近大额净流出，逐只查询避免竞争行情额度。 */
async function scanAlerts() {if(alertController)return;if(!state.endpoint){notify('请先连接新版行情服务');$('auto-alerts').checked=false;return;}if(state.busy||researchBusy||pathBusy||mainWindowBusy){notify('请等待当前查询完成后扫描');return;}alertReports.clear();renderAlerts();const market=state.market,symbols=(state.favorites.size?[...state.favorites]:state.rows.map(row=>row.symbol)).slice(0,20);alertController=new AbortController();const controller=alertController,template=researchEndpoint(marketConfig().example,'daily');$('scan-alerts').disabled=true;$('stop-alerts').hidden=false;let done=0,failed=0;try{for(const symbol of symbols){if(controller.signal.aborted)break;$('alert-status').textContent='正在扫描 '+symbol+' · '+done+' / '+symbols.length;const endpoint=new URL(template);endpoint.searchParams.set('symbol',symbol);endpoint.searchParams.set('direction','out');endpoint.searchParams.delete('date');try{const report=validateResearch(await requestJson(endpoint,()=>{},controller.signal),symbol);if(market!==state.market)break;alertReports.set(symbol,report);renderAlerts();}catch(error){if(controller.signal.aborted)break;failed++;$('alert-status').textContent=symbol+' 查询失败：'+error.message;}done++;}if(market===state.market)$('alert-status').textContent='已扫描 '+done+' / '+symbols.length+'，失败 '+failed+' · 近5个已结束交易日 · 阈值沿用研究窗口。';}finally{alertController=null;$('scan-alerts').disabled=false;$('stop-alerts').hidden=true;}}
/** 提醒只使用已成功获取的真实报告，不把查询失败算作没有风险。 */
function renderAlerts() {const events=[...alertReports.values()].flatMap(report=>(report.recentAlerts||[]).map(event=>({report,event}))).sort((a,b)=>a.event.main-b.event.main);$('alert-count').textContent=events.length+' 条';$('alert-list').innerHTML=events.length?events.map(({report,event})=>'<button class="alert-item" data-alert-symbol="'+escapeHtml(report.symbol)+'"><span><strong>'+escapeHtml(report.symbol)+' · '+escapeHtml(event.date)+'</strong><small>'+escapeHtml(report.name)+' · 点击复核事件与后续价格</small></span><strong class="negative">'+number(event.main,0,true)+' '+marketConfig().money+'</strong><span>查看历史 ↗</span></button>').join(''):'<p class="research-muted">已成功扫描的标的中，暂无达到当前阈值的近期事件。</p>';}
/** 仅在页面打开且用户启用时定期检查，关闭或断开后不继续轮询。 */
function toggleAlertMonitoring() {clearInterval(alertTimer);alertTimer=null;if(!$('auto-alerts').checked)return;scanAlerts();if(!$('auto-alerts').checked)return;alertTimer=setInterval(()=>{if(state.endpoint&&!document.hidden)scanAlerts();},300000);}
/** 委托处理事件明细、单股研究和明确的失败重试。 */
function handleResearchClick(event) {const row=event.target.closest('[data-research-event]'),alert=event.target.closest('[data-alert-symbol]');if(row)showResearchEvent(Number(row.dataset.researchEvent));if(alert)openResearch(alert.dataset.alertSymbol);if(event.target.closest('[data-retry-research]'))queryResearch();}
$('open-tail-research').addEventListener('click',()=>openResearch(marketConfig().example,'tail20'));
$('open-daily-research').addEventListener('click',()=>openResearch());
$('research-form').addEventListener('submit',queryResearch);$('research-kind').addEventListener('change',updateResearchKind);$('scan-alerts').addEventListener('click',scanAlerts);$('stop-alerts').addEventListener('click',()=>alertController?.abort());$('auto-alerts').addEventListener('change',toggleAlertMonitoring);$('retry-query').addEventListener('click',()=>refresh($('retry-query').dataset.date));document.addEventListener('click',handleResearchClick);document.addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.matches('[data-research-event]'))showResearchEvent(Number(event.target.dataset.researchEvent));});window.addEventListener('flow-market',resetResearchMarket);window.addEventListener('flow-disconnect',()=>{alertController?.abort();clearInterval(alertTimer);alertTimer=null;$('auto-alerts').checked=false;alertReports.clear();$('alert-list').innerHTML='';$('alert-count').textContent='已断开';});resetResearchMarket();updateResearchKind();
